function priceWithDiscount(price: number, customer: { loyaltyYears: number; isEmployee: boolean }): number {
  if (!Number.isFinite(price) || price < 0) {
    throw new Error("Invalid price");
  }

  let discount = 0;

  if (customer.isEmployee) {
    discount = 0.30;
  } else if (customer.loyaltyYears >= 10) {
    discount = 0.15;
  } else if (customer.loyaltyYears >= 3) {
    discount = 0.10;
  }

  const result = Math.max(0, price * (1 - discount));
  return Math.round(result * 100) / 100;
}

function runSuite(fn: (price: number, customer: { loyaltyYears: number; isEmployee: boolean }) => number): boolean {
  try {
    const user = (loyaltyYears: number) => ({ loyaltyYears, isEmployee: false });
    const employee = (loyaltyYears: number) => ({ loyaltyYears, isEmployee: true });

    const assertEqual = (actual: unknown, expected: unknown) => {
      if (!Object.is(actual, expected)) {
        throw new Error(`Expected ${String(expected)}, received ${String(actual)}`);
      }
    };

    const assertThrowsInvalidPrice = (price: number) => {
      let threw = false;
      try {
        fn(price, user(0));
      } catch (error) {
        threw = error instanceof Error && error.message === "Invalid price";
      }

      if (!threw) {
        throw new Error("Expected Invalid price error");
      }
    };

    assertEqual(fn(100, user(0)), 100);
    assertEqual(fn(100, user(2)), 100);
    assertEqual(fn(100, user(3)), 90);
    assertEqual(fn(100, user(9)), 90);
    assertEqual(fn(100, user(10)), 85);
    assertEqual(fn(100, employee(0)), 70);
    assertEqual(fn(100, employee(10)), 70);
    assertEqual(fn(19.99, user(0)), 19.99);
    assertEqual(fn(19.99, user(3)), 17.99);
    assertEqual(fn(0, user(0)), 0);
    assertEqual(fn(0, employee(0)), 0);
    assertEqual(fn(1, employee(0)), 0.7);
    assertEqual(fn(0.01, user(10)), 0.01);

    assertThrowsInvalidPrice(-1);
    assertThrowsInvalidPrice(-100);
    assertThrowsInvalidPrice(Infinity);
    assertThrowsInvalidPrice(-Infinity);
    assertThrowsInvalidPrice(NaN);

    return true;
  } catch {
    return false;
  }
}
